      if (step.current) item.setAttribute("aria-current", "step");
      item.appendChild(el("span", "sl-tl__when", step.when));
      item.appendChild(el("h3", "sl-tl__title", step.title));
      if (step.text) item.appendChild(el("p", "sl-tl__text", step.text));
      if (step.tag) item.appendChild(el("span", "sl-badge", step.tag));
