  /* ── Pager bar ────────────────────────────────────────────────── */
  function buildBar(total) {
    var bar = el("nav", "sl-bar");
    bar.setAttribute("aria-label", ui("pager"));
    var prev = el("button", "sl-btn");
    prev.type = "button";
    prev.setAttribute("aria-label", ui("prev"));
    prev.appendChild(icon("M15 6l-6 6 6 6"));
    prev.addEventListener("click", function () { go(deck.index - 1); });
    var next = el("button", "sl-btn");
    next.type = "button";
    next.setAttribute("aria-label", ui("next"));
    next.appendChild(icon("M9 6l6 6-6 6"));
    next.addEventListener("click", function () { go(deck.index + 1); });
    var count = el("span", "sl-count");
    count.setAttribute("aria-live", "polite");
    bar.appendChild(prev);
    bar.appendChild(count);
    bar.appendChild(next);
    var dots = [];
    if (total <= DOT_LIMIT) {
      var group = el("div", "sl-dots");
      group.setAttribute("role", "group");
      group.setAttribute("aria-label", ui("dots"));
      for (var i = 0; i < total; i += 1) {
        (function (target) {
          var dot = el("button", "sl-dot-btn");
          dot.type = "button";
          dot.setAttribute("aria-label", ui("goto", { n: target + 1 }));
          dot.addEventListener("click", function () { go(target); });
          group.appendChild(dot);
          dots.push(dot);
        })(i);
      }
      bar.appendChild(group);
    }
    return { bar: bar, prev: prev, next: next, count: count, dots: dots };
  }

  /* ── Paging ───────────────────────────────────────────────────── */
